-- کالاهای فهرست موجودی ۱۳ آبان ۱۴۰۵ که هنوز در فروشگاه نبودند؛ هر مدل یک صفحه.
-- نسخه‌های یک مدل (Full/Light فرونیوس، D/P تارو، P/SE سانویز) یک صفحه‌اند و در متن آمده‌اند.
-- ON CONFLICT DO NOTHING: اگر نامکی از قبل هست، دست نمی‌خورد؛ چیزی که در پنل ویرایش شده می‌ماند.
-- متن‌ها فقط عددهایی را می‌گویند که در دیتاشیت سازنده دیده شده؛ بقیه کلی مانده‌اند.
INSERT INTO `products` (`slug`, `name`, `brand`, `spec`, `spec_unit`, `cat`, `kind`, `subkind`, `phase`, `power_min`, `power_max`, `official`, `in_stock`, `sort_order`, `body`) VALUES
('fronius-primo-5-0-1', 'اینورتر تک‌فاز Fronius Primo 5.0‑1', 'FRONIUS', '۵', 'kW · تک‌فاز', 'home', 'inverter', 'string', 'single', 5, 5, 0, 1, 101,
 'اینورتر متصل به شبکهٔ تک‌فاز ۵ کیلوواتی فرونیوس اتریش برای خانه، ویلا و واحد تجاری کوچک. دو ردیاب MPPT دارد، پس پنل‌های دو جهت سقف یا پنل‌های سایه‌دار و بی‌سایه روی دو ورودی جدا می‌روند، و الگوریتم Dynamic Peak Manager در سایهٔ جزئی قلهٔ واقعی منحنی توان را پیدا می‌کند. در دو نسخه موجود است: Full با پایش از راه دور (WLAN و LAN) و Light بدون آن. برای قرارداد بلندمدت فروش برق، نسخهٔ Full پیشنهاد می‌شود، چون خرابی یک رشته را همان روز نشان می‌دهد.'),
('kaco-blueplanet-5-0-nx1-m2', 'اینورتر تک‌فاز KACO blueplanet 5.0 NX1 M2', 'KACO', '۵', 'kW · تک‌فاز', 'home', 'inverter', 'string', 'single', 5, 5, 0, 1, 102,
 'اینورتر متصل به شبکهٔ تک‌فاز ۵ کیلوواتی از KACO new energy آلمان، از سری blueplanet NX1. گزینه‌ای میان‌رده برای سیستم‌های خانگی و ویلایی که به پله‌ی ۵ کیلووات الزام انشعاب یا فروش برق تضمینی می‌خورند. پیش از سفارش، تعداد پنل در هر رشته را با ولتاژ ورودی این مدل و سرمای زمستان محل نصب چک کنید.'),
('deye-sun-5k-g05p1', 'اینورتر تک‌فاز Deye SUN‑5K‑G05P1', 'DEYE', '۵', 'kW · تک‌فاز', 'home', 'inverter', 'string', 'single', 5, 5, 0, 1, 103,
 'اینورتر متصل به شبکهٔ تک‌فاز ۵ کیلوواتی دی، مدل SUN-5K-G05P1-EU-AM2، با دو ردیاب MPPT و بازده حداکثر تا ۹۷٫۵ درصد. گزینهٔ اقتصادی پله‌ی ۵ کیلووات. توجه: این مدل هیبرید نیست و باتری نمی‌گیرد، پس در قطعی برق کار نمی‌کند؛ برای برق اضطراری، ذخیره‌سازهای یکپارچهٔ دی را ببینید. ورودی DC آن ولتاژ پایین‌تری از اینورترهای سه‌فاز دارد؛ در سرمای کرمان با پنل‌های ۵۵۰ تا ۵۸۰ وات، رشته‌ها حداکثر ۹ پنلی بسته شوند.'),
('sunways-stt-5ktl', 'اینورتر سه‌فاز Sunways STT‑5KTL', 'SUNWAYS', '۵', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 5, 5, 0, 1, 104,
 'اینورتر متصل به شبکهٔ سه‌فاز ۵ کیلوواتی سانویز، در دو نسخهٔ P و SE. سری STT دو ردیاب MPPT، بازده حداکثر ۹۸٫۶ درصد و بدنهٔ IP65 دارد. برای ساختمانی که انشعاب سه‌فاز دارد ولی به پله‌ی ۵ کیلووات می‌خورد، انتخاب درستی است: اینورتر تک‌فاز روی انشعاب سه‌فاز همهٔ تولید را روی یک فاز می‌ریزد و عدم‌تعادل می‌سازد، این مدل توان را بین سه فاز پخش می‌کند.'),
('kaco-blueplanet-10-0-nx3-m2', 'اینورتر سه‌فاز KACO blueplanet 10.0 NX3 M2', 'KACO', '۱۰', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 10, 10, 0, 1, 105,
 'اینورتر متصل به شبکهٔ سه‌فاز ۱۰ کیلوولت‌آمپری KACO آلمان با دو ردیاب MPPT. بازهٔ ولتاژ MPP آن از ۱۵۰ تا ۱۰۰۰ ولت و حداکثر ولتاژ ورودی ۱۱۰۰ ولت است، و تا ۱۵ کیلووات پنل در سمت DC می‌پذیرد. بازهٔ ولتاژ پهن یعنی دست طراح در چیدن رشته‌ها باز است؛ با پنل‌های ۵۵۰ تا ۵۸۰ وات در سرمای کرمان تا ۱۹ پنل در هر رشته.'),
('fronius-symo-10-0-3-m', 'اینورتر سه‌فاز Fronius Symo 10.0‑3‑M', 'FRONIUS', '۱۰', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 10, 10, 0, 1, 106,
 'اینورتر متصل به شبکهٔ سه‌فاز ۱۰ کیلوواتی فرونیوس، رایج‌ترین انتخاب برای پله‌ی ۱۰ کیلووات الزام انشعاب ساختمان. دو ردیاب MPPT دارد و Dynamic Peak Manager در سایهٔ کولر، منبع آب یا دیوار جان‌پناه، کل منحنی توان را می‌پیماید تا قلهٔ واقعی را پیدا کند. نسخهٔ Full پایش از راه دور دارد و نسخهٔ Light ندارد. با حداکثر ورودی ۱۰۰۰ ولت، رشته‌ها در سرمای کرمان حداکثر ۱۷ پنلی بسته شوند.'),
('fronius-symo-advanced-15-0-3-m', 'اینورتر سه‌فاز Fronius Symo Advanced 15.0‑3‑M', 'FRONIUS', '۱۵', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 15, 15, 0, 1, 107,
 'اینورتر متصل به شبکهٔ سه‌فاز ۱۵ کیلوواتی فرونیوس از سری Symo Advanced، برای پله‌ی ۱۵ کیلووات الزام انشعاب، کارگاه و ساختمان تجاری. دو ردیاب MPPT برای جدا کردن بخش‌های سایه‌دار یا جهت‌های مختلف سقف. در دو نسخهٔ Full (با پایش از راه دور) و Light موجود است.'),
('sunways-stt-15ktl-p', 'اینورتر سه‌فاز Sunways STT‑15KTL‑P', 'SUNWAYS', '۱۵', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 15, 15, 0, 1, 108,
 'اینورتر متصل به شبکهٔ سه‌فاز ۱۵ کیلوواتی سانویز با دو ردیاب MPPT، بازده حداکثر ۹۸٫۶ درصد و بدنهٔ IP65. گزینهٔ اقتصادی پله‌ی ۱۵ کیلووات الزام انشعاب در کنار فرونیوس Symo Advanced. بازده اسمی اینورترهای خوب در یک توان به هم نزدیک است؛ تفاوت اصلی در پایش، خدمات پس از فروش و پنجرهٔ ولتاژ است.'),
('fronius-symo-20-0-3-m', 'اینورتر سه‌فاز Fronius Symo 20.0‑3‑M', 'FRONIUS', '۲۰', 'kW · سه‌فاز', 'home', 'inverter', 'string', 'three', 20, 20, 0, 1, 109,
 'اینورتر متصل به شبکهٔ سه‌فاز ۲۰ کیلوواتی فرونیوس، بزرگ‌ترین عضو خانوادهٔ Symo و جواب پله‌ی ۲۰ کیلووات الزام انشعاب. دو ردیاب MPPT و Dynamic Peak Manager دارد. در دو نسخه موجود است: Advanced Full با پایش از راه دور، و Light.'),
('fronius-eco-25-0-3-s', 'اینورتر سه‌فاز Fronius ECO 25.0‑3‑S', 'FRONIUS', '۲۵', 'kW · سه‌فاز', 'industrial', 'inverter', 'string', 'three', 25, 25, 0, 1, 110,
 'اینورتر سه‌فاز ۲۵ کیلوواتی فرونیوس برای سیستم‌های تجاری و آرایه‌های بزرگ و یکدست. یک ردیاب MPPT و بازده حداکثر ۹۸٫۲ درصد دارد. نکتهٔ طراحی مهم: پنجرهٔ ولتاژ MPP آن باریک است، از ۵۸۰ تا ۸۵۰ ولت، پس با پنل‌های ۵۸۰ وات رشته‌ها باید ۱۶ یا ۱۷ پنلی باشند؛ رشتهٔ کوتاه‌تر در گرمای تابستان از پنجره بیرون می‌افتد. نسخهٔ Full پایش از راه دور (WLAN و LAN) دارد و نسخهٔ Light داده را روی USB ثبت می‌کند.'),
('deye-sun-25k-g05', 'اینورتر سه‌فاز Deye SUN‑25K‑G05', 'DEYE', '۲۵', 'kW · سه‌فاز', 'industrial', 'inverter', 'string', 'three', 25, 25, 0, 1, 111,
 'اینورتر متصل به شبکهٔ سه‌فاز ۲۵ کیلوواتی دی با دو ردیاب MPPT، بازده حداکثر ۹۸٫۶ درصد و بازده ردیابی بالای ۹۹ درصد. گزینهٔ اقتصادی برای کارگاه، ساختمان تجاری و سقف‌هایی که دو جهت یا دو بخش متفاوت دارند؛ برخلاف اینورترهای تک‌ردیابه، هر بخش سقف جدا بهینه می‌شود.'),
('fronius-tauro-eco-50-3', 'اینورتر سه‌فاز Fronius Tauro ECO 50‑3', 'FRONIUS', '۵۰', 'kW · نصب بیرونی', 'industrial', 'inverter', 'string', 'three', 50, 50, 0, 1, 112,
 'اینورتر سه‌فاز ۵۰ کیلوواتی فرونیوس برای محیط‌های سخت: بدنهٔ IP65، کار در دمای منفی ۴۰ تا مثبت ۶۵ درجه، خنک‌کاری فعال با بدنهٔ دوجداره و بازده حداکثر ۹۸٫۵ درصد. در دو نسخه موجود است: D که رشته‌ها مستقیم با کانکتور MC4 به آن وصل می‌شوند و فیوز رشته داخل خود دستگاه است (کامباینر ۲۰ آمپر)، و P که برای آرایه‌های دور طراحی شده و رشته‌ها در کامباینر کنار پنل جمع می‌شوند. سخت‌افزار هر دو یکی است.'),
('sungrow-sg50cx', 'اینورتر سه‌فاز Sungrow SG50CX', 'SUNGROW', '۵۰', 'kW · سه‌فاز', 'industrial', 'inverter', 'string', 'three', 50, 50, 0, 1, 113,
 'اینورتر تجاری سه‌فاز ۵۰ کیلوواتی سانگرو با پنج ردیاب MPPT مستقل، بازده حداکثر ۹۸٫۷ و اروپایی ۹۸٫۴ درصد، حداکثر ولتاژ ورودی ۱۱۰۰ ولت و قابلیت بازیابی PID. پنج ردیاب یعنی سقف سولهٔ چندتکه یا با جهت‌های مختلف بدون افت مصالحه‌ای کار می‌کند؛ هر گروه رشته جدا بهینه می‌شود.'),
('huawei-sun2000-50ktl-m3', 'اینورتر سه‌فاز Huawei SUN2000‑50KTL‑M3', 'HUAWEI', '۵۰', 'kW · سه‌فاز', 'industrial', 'inverter', 'string', 'three', 50, 50, 0, 1, 114,
 'اینورتر تجاری سه‌فاز ۵۰ کیلوواتی هوآوی با چهار ردیاب MPPT، بازده حداکثر ۹۸٫۵ درصد، بازهٔ MPP از ۲۰۰ تا ۱۰۰۰ ولت و حداکثر ورودی ۱۱۰۰ ولت. حفاظت هوشمند در برابر قوس الکتریکی دارد که جرقهٔ DC را پیش از شعله‌ور شدن تشخیص می‌دهد و قطع می‌کند، و اسکن منحنی I-V که رشتهٔ معیوب را از راه دور نشان می‌دهد. برای سقف‌های عایق‌دار و ساندویچ‌پنل، انتخاب ایمن‌تری است.'),
('fronius-tauro-eco-100-3', 'اینورتر سه‌فاز Fronius Tauro ECO 100‑3', 'FRONIUS', '۱۰۰', 'kW · نصب بیرونی', 'industrial', 'inverter', 'string', 'three', 100, 100, 0, 1, 115,
 'اینورتر سه‌فاز ۱۰۰ کیلوواتی فرونیوس برای سقف سوله، کارخانه و نیروگاه کوچک: بدنهٔ IP65، کار در دمای منفی ۴۰ تا مثبت ۶۵ درجه، خنک‌کاری فعال و بازده حداکثر ۹۸٫۵ درصد، با ظرفیت تا ۱۵۰ کیلووات پنل در سمت DC. نسخهٔ D رشته‌ها را مستقیم با کانکتور MC4 و فیوز داخلی می‌گیرد و کامباینر جدا لازم ندارد؛ نسخهٔ P ورودی کامباینرشده با کابل ضخیم دارد و برای آرایهٔ دور از اینورتر مناسب است.'),
('deye-sun-100k-g03', 'اینورتر سه‌فاز Deye SUN‑100K‑G03', 'DEYE', '۱۰۰', 'kW · سه‌فاز', 'industrial', 'inverter', 'string', 'three', 100, 100, 0, 1, 116,
 'اینورتر تجاری سه‌فاز ۱۰۰ کیلوواتی دی، گزینهٔ اقتصادی صد کیلووات، با بازده حداکثر ۹۸٫۸ درصد، بازهٔ MPP از ۲۰۰ تا ۸۵۰ ولت و حداکثر ورودی ۱۰۰۰ ولت. قطع‌کن قوس الکتریکی (AFCI) در این مدل اختیاری است؛ برای سقف‌های عایق‌دار یا ساندویچ‌پنل، هنگام سفارش آن را بخواهید.'),
('goodwe-gw250k-ht', 'اینورتر نیروگاهی GoodWe GW250K‑HT', 'GOODWE', '۲۵۰', 'kW · ۱۵۰۰V', 'industrial', 'inverter', 'string', 'three', 250, 250, 0, 1, 117,
 'اینورتر رشته‌ای نیروگاهی ۲۵۰ کیلوواتی گودوی با ورودی ۱۵۰۰ ولت، بازهٔ MPP از ۵۰۰ تا ۱۵۰۰ ولت، دوازده ردیاب MPPT و خروجی ۸۰۰ ولت. ولتاژ بالای ورودی یعنی پنل بیشتر در هر رشته و رشته، کانکتور و کابل کمتر؛ خروجی ۸۰۰ ولتی همان توان را با جریان نصف به ترانس می‌فرستد و تلفات کابل را یک‌چهارم می‌کند. تشخیص منحنی I-U، پایش رطوبت داخلی و ارتباط PLC روی کابل قدرت هم دارد که کابل‌کشی داده را در سایت‌های دور حذف می‌کند.'),
('deye-rw-f5-3-1h3', 'ذخیره‌ساز یکپارچه Deye RW‑F5.3‑1H3', 'DEYE', '۵٫۳۲', 'kWh · All‑in‑One', 'home', 'storage', 'all-in-one', NULL, 5.32, 5.32, 0, 1, 118,
 'اینورتر هیبرید و باتری لیتیوم‌آهن‌فسفات ۵٫۳۲ کیلووات‌ساعتی دی در یک بدنه، با ولتاژ اسمی ۵۱٫۲ ولت، پایش با WiFi و بلوتوث و خنک‌کاری طبیعی بی‌صدا. به گفتهٔ سازنده در قطعی برق در ۴ میلی‌ثانیه به باتری سوئیچ می‌کند؛ کوتاه‌تر از زمانی که منبع تغذیهٔ کامپیوتر بدون برق دوام می‌آورد، پس مودم و کامپیوتر ریست نمی‌شوند. برای مغازه، دفتر و خانه‌ای که قطعی روزانه دارد.'),
('deye-ae-fs2-0-2h2', 'ذخیره‌ساز بالکنی Deye AE‑FS2.0‑2H2', 'DEYE', '۲', 'kWh · بالکنی', 'home', 'storage', 'all-in-one', NULL, 2, 2, 0, 1, 119,
 'ذخیره‌ساز کوچک بالکنی دی: خروجی ۱ کیلووات و باتری لیتیوم‌آهن‌فسفات ۲ کیلووات‌ساعتی در یک بدنهٔ ضدآب، با حالت UPS و ۱۰ سال ضمانت. برای آپارتمان‌نشینی که پشت‌بام ندارد: کنار پریز می‌نشیند، از برق شهر یا یکی دو پنل بالکنی شارژ می‌شود و در قطعی، مودم، چراغ، لپ‌تاپ و تلویزیون را چند ساعت روشن نگه می‌دارد. یخچال‌های اینورتری معمولاً مشکلی ندارند؛ برای یخچال قدیمی پیش از خرید تست شود، چون کمپرسور در لحظهٔ روشن شدن چند برابر حالت عادی برق می‌کشد.'),
('pntech-mc4-crimping-tool', 'ابزار پرس کانکتور MC4 PNTECH', 'PNTECH', 'پرس', 'MC4', 'home', 'tool', NULL, NULL, NULL, NULL, 0, 1, 120,
 'ابزار پرس مخصوص پین کانکتورهای MC4. اتصالی که با انبردست پرس شود لق می‌ماند و مقاومت تماسش بالا می‌رود؛ همهٔ جریان رشته از همین نقطهٔ کوچک رد می‌شود و گرما همان‌جا جمع می‌شود، و این یکی از شروع‌های رایج آتش در سیستم‌های خورشیدی است. پرس استاندارد، فشار یکنواخت و تکرارپذیر روی پین می‌گذارد.'),
('pntech-mc4-spanner', 'آچار کانکتور MC4 PNTECH', 'PNTECH', 'آچار', 'MC4', 'home', 'tool', NULL, NULL, NULL, NULL, 0, 1, 121,
 'آچار مخصوص سفت کردن مهرهٔ کانکتور MC4 و باز کردن قفل کانکتورهای جفت‌شده بی‌آنکه بدنه یا آب‌بندی آن آسیب ببیند. مهرهٔ شل، آب‌بندی کابل را از بین می‌برد و رطوبت به اتصال می‌رسد؛ باز کردن کانکتور با پیچ‌گوشتی هم زبانهٔ قفل را می‌شکند.'),
('pntech-stripping-tool', 'سیم‌لخت‌کن PNTECH', 'PNTECH', 'سیم‌لخت‌کن', 'کابل DC', 'home', 'tool', NULL, NULL, NULL, NULL, 0, 1, 122,
